const rows = $input.all().map(item => item.json);

const cleanRows = rows.filter(row =>
  Object.values(row).some(value => value !== null && value !== "")
);

const processedRows = cleanRows.map(row => {
  const newRow = { ...row };

  for (const key of Object.keys(newRow)) {
    const value = newRow[key];

    if (
      typeof value === "string" &&
      value.trim() !== "" &&
      !isNaN(value)
    ) {
      newRow[key] = Number(value);
    }
  }

  return newRow;
});

const columns = Object.keys(processedRows[0] || {});

const numericColumns = columns.filter(column =>
  processedRows.some(row => typeof row[column] === "number")
);

const statistics = {};

for (const column of numericColumns) {

  const values = processedRows
    .map(row => row[column])
    .filter(value => typeof value === "number" && !isNaN(value));

  if (values.length === 0) continue;

  const total = values.reduce((sum, value) => sum + value, 0);

  const mean = total / values.length;

  const min = Math.min(...values);
  const max = Math.max(...values);

  statistics[column] = {
    count: values.length,
    sum: total,
    mean: mean,
    min: min,
    max: max
  };
}

return [{
  json: {
    row_count: processedRows.length,
    column_count: columns.length,
    columns,
    numeric_columns: numericColumns,
    statistics,
    sample_data: processedRows.slice(0, 10),
    data: processedRows
  }
}];

const rawText = 
  $json.output?.[0]?.content?.[0]?.text 
  || $json.text 
  || $json.output 
  || $json.response 
  || "";

// --- Simple Markdown → HTML converter ---
function markdownToHtml(md) {
  let html = md;

  // Escape existing HTML tags first
  html = html.replace(/</g, "&lt;").replace(/>/g, "&gt;");

  // Headers
  html = html.replace(/^### (.*$)/gim, '<h3 style="color:#2c3e50; margin-top:24px;">$1</h3>');
  html = html.replace(/^## (.*$)/gim, '<h2 style="color:#1a1a2e; border-bottom:2px solid #4a90d9; padding-bottom:6px; margin-top:32px;">$1</h2>');
  html = html.replace(/^# (.*$)/gim, '<h1 style="color:#1a1a2e;">$1</h1>');

  // Bold
  html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

  // Horizontal rules
  html = html.replace(/^---$/gim, '<hr style="border:none; border-top:1px solid #e0e0e0; margin:24px 0;">');

  // Tables (basic markdown tables)
  html = html.replace(/((?:^\|.*\|\n?)+)/gim, (tableBlock) => {
    const rows = tableBlock.trim().split("\n").filter(r => r.trim() !== "");
    if (rows.length < 2) return tableBlock;

    const headerCells = rows[0].split("|").map(c => c.trim()).filter(Boolean);
    const bodyRows = rows.slice(2); // skip header separator row (---|---)

    let table = '<table style="width:100%; border-collapse:collapse; margin:16px 0; font-size:14px;">';
    table += '<thead><tr>';
    headerCells.forEach(cell => {
      table += `<th style="background:#4a90d9; color:#fff; padding:10px; text-align:left; border:1px solid #ddd;">${cell}</th>`;
    });
    table += '</tr></thead><tbody>';

    bodyRows.forEach((row, i) => {
      const cells = row.split("|").map(c => c.trim()).filter(Boolean);
      const bg = i % 2 === 0 ? "#f9fbfd" : "#ffffff";
      table += `<tr style="background:${bg};">`;
      cells.forEach(cell => {
        table += `<td style="padding:10px; border:1px solid #ddd;">${cell}</td>`;
      });
      table += '</tr>';
    });

    table += '</tbody></table>';
    return table;
  });

  // Bullet lists
  html = html.replace(/^\s*-\s+(.*$)/gim, '<li style="margin-bottom:6px;">$1</li>');
  html = html.replace(/(<li.*<\/li>\n?)+/g, (match) => `<ul style="padding-left:20px;">${match}</ul>`);

  // Line breaks / paragraphs (only for lines not already wrapped in a tag)
  html = html
    .split("\n")
    .map(line => {
      const trimmed = line.trim();
      if (trimmed === "" || /^<(h1|h2|h3|hr|table|ul|li|thead|tbody|tr|th|td)/.test(trimmed)) {
        return trimmed;
      }
      return `<p style="line-height:1.6; color:#333; margin:8px 0;">${trimmed}</p>`;
    })
    .join("\n");

  return html;
}

const analysisHtml = markdownToHtml(rawText);

const html = `
<html>
<body style="font-family: 'Segoe UI', Arial, sans-serif; background:#f4f6f8; padding:24px; margin:0;">
  <div style="max-width:700px; margin:0 auto; background:#fff; border-radius:10px; overflow:hidden; box-shadow:0 2px 8px rgba(0,0,0,0.08);">

    <div style="background:linear-gradient(135deg,#4a90d9,#2c5f9e); padding:28px 32px;">
      <h1 style="color:#fff; margin:0; font-size:24px;">📊 AI Data Analysis Report</h1>
      <p style="color:#dce8f7; margin:6px 0 0; font-size:14px;">Automated insight generated from your submitted dataset</p>
    </div>

    <div style="padding:28px 32px;">
      <p style="color:#333;">Hello,</p>
      <p style="color:#333;">Please find below the automated analysis of the submitted dataset.</p>

      ${analysisHtml}

      <hr style="border:none; border-top:1px solid #e0e0e0; margin:28px 0 16px;">
      <p style="font-size:12px; color:#999; text-align:center;">
        This report was automatically generated using n8n and OpenAI.
      </p>
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    subject: "📊 Automated Data Analysis Report",
    email_html: html,
    analysis: rawText
  }
}];
